316	  cacheTag(eventsTag, eventTag(slug));
317	  const event = await fetchEventBySlug(slug, {
318	    preferConfiguredOrigin: true,
319	    throwOnError: true,
320	  });
321	  if (!event) {
322	    // Genuine 404: cache briefly so a newly-created event isn't stuck on
323	    // "not found" metadata for hours. "minutes" not "seconds" — seconds is a
324	    // PPR dynamic hole and would re-break the static shell.
325	    cacheLife("minutes");
326	    return null;
327	  }
328	  cacheLife("hours");
329	  return event;
330	}
