542	 * Fetch events categorized by category.
543	 * During build phase (SSG), calls external API directly to avoid internal proxy issues.
544	 * At runtime (ISR/SSR), uses internal API proxy for better caching and security.
545	 */
546	export async function fetchCategorizedEvents(
547	  maxEventsPerCategory?: number,
548	): Promise<CategorizedEvents> {
549	  const apiUrl = getApiUrl();
550	
551	  // During build phase, bypass internal proxy and call external API directly
552	  // This ensures SSG pages (homepage) can fetch data during next build
553	  if (isBuildPhase) {
554	    try {
555	      const data = await fetchCategorizedEventsExternal(maxEventsPerCategory);
556	      const validated = parseCategorizedEvents(data);
557	      if (!validated) {
558	        console.error("fetchCategorizedEvents: Build phase validation failed");
559	        return {};
560	      }
561	      return validated;
562	    } catch (e) {
563	      console.error(
564	        "fetchCategorizedEvents: Build phase external fetch failed:",
565	        e,
566	      );
567	      return {};
568	    }
569	  }
570	
571	  // Runtime: use direct external API call with caching
572	  // This avoids internal API proxy issues
573	  try {
574	    const params = new URLSearchParams();
575	    if (maxEventsPerCategory !== undefined) {
576	      params.append("maxEventsPerCategory", String(maxEventsPerCategory));
577	    }
578	
579	    const queryString = params.toString() ? `?${params.toString()}` : "";
580	    const finalUrl = `${apiUrl}/events/categorized${queryString}`;
581	
582	    const response = await fetchWithHmac(finalUrl, {
583	      next: { revalidate: 600, tags: ["events", "events:categorized"] },
584	      headers: {
585	        Accept: "application/json",
586	      },
587	    });
588	
589	    if (!response.ok) {
590	      const errorText = await response
591	        .text()
592	        .catch(() => "Unable to read error response");
593	      console.error(
594	        `fetchCategorizedEvents: HTTP error! status: ${response.status}, url: ${finalUrl}, error: ${errorText}`,
595	      );
596	      throw new Error(`HTTP error! status: ${response.status}`);
597	    }
598	    const data = await response.json();
599	    const validated = parseCategorizedEvents(data);
600	    if (!validated || Object.keys(validated).length === 0) {
601	      console.error("fetchCategorizedEvents: Runtime validation failed");
602	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
603	    }
604	    return validated;
605	  } catch {
606	    // If direct fetch fails, try external API helper as fallback (handles edge cases)
607	    try {
608	      const data = await fetchCategorizedEventsExternal(maxEventsPerCategory);
609	      const validated = parseCategorizedEvents(data);
610	      if (validated && Object.keys(validated).length > 0) {
611	        return validated;
612	      }
613	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
614	    } catch (fallbackError) {
615	      // Sanitize error logging to prevent information disclosure
616	      const errorMessage = getSanitizedErrorMessage(fallbackError);
617	      console.error(
618	        "fetchCategorizedEvents: Both direct and external API failed:",
619	        errorMessage,
620	      );
621	      return isE2ETestMode ? buildE2EFallbackCategorizedEvents() : {};
622	    }
623	  }
624	}
