685	/**
686	 * Insert ads at deterministic positions in the event list.
687	 * Uses fixed spacing instead of Math.random() to ensure the component tree
688	 * is identical across renders — required for cacheComponents (RSC resumption).
689	 */
690	function insertAdsDeterministic(
691	  events: EventSummaryResponseDTO[],
692	  ads: AdEvent[],
693	  spacing = 5,
694	  startFrom = 3,
695	): ListEvent[] {
696	  const result: ListEvent[] = [...events];
697	
698	  ads.forEach((ad, i) => {
699	    // Fixed position: startFrom + i * spacing, adjusted for prior insertions
700	    const index = startFrom + i * (spacing + 1);
701	    if (index <= result.length) {
702	      result.splice(index, 0, ad);
703	    }
704	  });
705	
706	  return result;
707	}
