547	  ...rest
548	}: GeneratePagesDataProps & {
549	  placeTypeLabel: PlaceTypeAndLabel;
550	  locale?: AppLocale;
551	}): Promise<PageData> {
552	  const pageData = await generatePagesDataCached(rest);
