58	export async function generateMetadata({
59	  params,
60	}: {
61	  params: Promise<MonthStaticPathParams>;
62	}) {
63	  const locale = (await rootLocale()) as AppLocale;
64	  const t = await getTranslations({ locale, namespace: "Pages.SitemapMonth" });
65	  const tConstants = await getTranslations({
66	    locale,
67	    namespace: "Components.Constants",
68	  });
69	  const tNotFound = await getTranslations({ locale, namespace: "App.NotFound" });
70	  const { town, year, month } = await params;
71	
72	  // Validate required params
73	  if (!town || !year || !month || !isValidPlace(town)) {
74	    return {
75	      title: tNotFound("title"),
76	      description: tNotFound("description"),
77	    };
78	  }
79	
80	  // Validate year is numeric and reasonable
81	  const yearNum = Number(year);
82	  if (!Number.isFinite(yearNum) || yearNum < MIN_VALID_YEAR || yearNum > MAX_VALID_YEAR) {
83	    return {
84	      title: tNotFound("title"),
85	      description: tNotFound("description"),
86	    };
87	  }
88	
89	  const monthLabels = (tConstants.raw("months") as string[]) || [];
90	  const monthIndex = resolveMonthIndexFromSlug(month);
91	  if (monthIndex === null) {
92	    return {
93	      title: tNotFound("title"),
94	      description: tNotFound("description"),
95	    };
96	  }
97	  const canonicalMonthSlug = DEFAULT_MONTHS_URL[monthIndex];
98	  const monthLabel =
99	    monthLabels[monthIndex] || normalizeMonthParam(canonicalMonthSlug).label;
100	  // Tolerate backend 5xx for place lookup (cosmetic; town slug is an acceptable
101	  // fallback). Prevents archive 500s from intermittent backend errors — the
102	  // main 5xx source per GSC on /sitemap/<town>/<year>/<month>.
103	  const place = await fetchPlaceBySlugForMetadata(town).catch(() => null);
104	  const townLabel = place?.name || town;
105	  const placeType: "region" | "town" =
106	    place?.type === "CITY" ? "town" : "region";
107	  const locationPhrase = formatPlacePreposition(
108	    townLabel,
109	    placeType,
110	    locale,
111	    false
112	  );
113	
114	  // Probe events to set robots policy: noindex empty months so GSC stops
115	  // flagging them as soft 404 / "Crawled - currently not indexed". Uses the
116	  // metadata-safe fetchEventsForMetadata, not the fetchMonthEvents wrapper
117	  // Page uses below — fetchMonthEvents goes through fetchWithHmac, which
118	  // unconditionally calls connection() and breaks the static shell if
119	  // called from generateMetadata. See docs/incidents/
120	  // 2026-06-13-cachecomponents-metadata-resume-mismatch.md.
121	  const { from, until } = getHistoricDates(
122	    canonicalMonthSlug,
123	    Number(year),
124	    DEFAULT_MONTHS_URL
125	  );
126	  const fromStr = from.toISOString().split("T")[0];
127	  const toStr = until.toISOString().split("T")[0];
128	  const events = await fetchEventsForMetadata({
129	    place: town,
130	    from: fromStr,
131	    to: toStr,
132	    size: MAX_EVENTS_PER_PAGE,
133	  });
134	  const realEventCount = Array.isArray(events.content)
135	    ? (events.content as EventSummaryResponseDTO[]).filter((e) => !e.isAd)
136	      .length
137	    : 0;
138	  const robotsOverride = realEventCount === 0 ? "noindex, follow" : undefined;
139	
140	  return buildPageMeta({
141	    title: t("metaTitle", { town: townLabel, month: monthLabel, year }),
142	    description: t("metaDescription", {
143	      locationPhrase,
144	      month: monthLabel,
145	      year,
146	      town: townLabel,
147	    }),
148	    canonical: `${siteUrl}/sitemap/${town}/${year}/${canonicalMonthSlug}`,
149	    locale,
150	    robotsOverride,
151	  });
152	}
