1	import { cache } from "react";
2	import { cacheLife, cacheTag } from "next/cache";
3	import { fetchEventCountExternal } from "@lib/api/events-external";
4	import {
5	  getInternalApiUrl,
6	  getVercelProtectionBypassHeaders,
7	} from "@utils/api-helpers";
8	import { eventsTag } from "@lib/cache/tags";
9	import { SITEMAP_MIN_EVENTS_FOR_EXPANSION } from "@utils/constants";
10	import type { PlaceType } from "types/common";
11	
12	async function resolvePlaceExpandability(
13	  slug: string,
14	  type: PlaceType,
15	  fetchCount: (slug: string) => Promise<number | null>,
16	): Promise<boolean> {
17	  if (type !== "town") return true;
18	  if (!slug || slug === "catalunya") return true;
19	  try {
20	    const count = await fetchCount(slug);
21	    return count === null || count >= SITEMAP_MIN_EVENTS_FOR_EXPANSION;
22	  } catch {
23	    // Fail open on unexpected errors so transient failures don't shrink
24	    // sitemap or hide internal links.
25	    return true;
26	  }
27	}
28	
29	// Metadata-only count reader: hits the internal API route with a plain,
30	// tagged `fetch()` instead of `fetchEventCountExternal` (which goes through
31	// `fetchWithHmac`, and that calls `connection()` unconditionally). Calling a
32	// dynamic API from inside a "use cache" scope defeats the whole point of
33	// getPlaceExpandabilityForMetadata below — it would stay a resume-mismatch
34	// hazard despite the "use cache" wrapper.
35	async function fetchEventCountForMetadata(slug: string): Promise<number | null> {
36	  const url = await getInternalApiUrl(
37	    `/api/events?place=${encodeURIComponent(slug)}&size=1`,
38	    { preferConfiguredOrigin: true },
39	  );
40	  const response = await fetch(url, {
41	    headers: getVercelProtectionBypassHeaders(),
42	    next: { revalidate: 600, tags: [eventsTag] },
43	  });
44	  if (!response.ok) return null;
45	  const data = await response.json();
46	  return typeof data?.totalElements === "number" ? data.totalElements : null;
47	}
48	
49	/**
50	 * Determines whether a place has enough event depth to warrant filter
51	 * expansion (date/category internal links and sitemap entries).
52	 *
53	 * REGIONs and the virtual "catalunya" slug always qualify (they aggregate
54	 * events from many cities). CITYs/towns qualify only when their total event
55	 * count meets the threshold.
56	 *
57	 * On API failure or unexpected error, returns true (fail-open) so transient
58	 * issues don't silently hide internal links or shrink the sitemap.
59	 *
60	 * Single source of truth: used by /[place] pages (SSR depth + noindex meta),
61	 * PlacePageShell (explore-nav internal links), and app/sitemap-places/[...parts]
62	 * (sitemap entries). All four surfaces stay in lock-step — if sitemap drops a
63	 * URL, the page also stops emitting internal links to it. Otherwise Googlebot
64	 * keeps discovering them via crawl, treats them as near-duplicates of the
65	 * parent, and buckets them as "Crawled — currently not indexed" (Dec 2025–May
66	 * 2026 GSC drop, ~93K URLs).
67	 *
68	 * Lives in `lib/seo/` rather than `utils/` because it depends on React caching
69	 * and API I/O; `utils/` is reserved for deterministic, side-effect-free
70	 * helpers.
71	 */
72	export const getPlaceExpandability = cache(
73	  (slug: string, type: PlaceType): Promise<boolean> =>
74	    resolvePlaceExpandability(slug, type, fetchEventCountExternal),
75	);
76	
77	// Metadata-only reader: wraps the same check in `"use cache"` so
78	// generateMetadata stays prerenderable under cacheComponents. See
79	// docs/incidents/2026-06-13-cachecomponents-metadata-resume-mismatch.md.
80	export async function getPlaceExpandabilityForMetadata(
81	  slug: string,
82	  type: PlaceType,
83	): Promise<boolean> {
84	  "use cache";
85	  cacheTag(eventsTag);
86	  cacheLife("hours");
87	  return resolvePlaceExpandability(slug, type, fetchEventCountForMetadata);
88	}
