1	// Metadata-only readers for place/region lookups. Kept out of lib/api/places.ts,
2	// lib/api/regions.ts, and utils/location-helpers.ts because those files are
3	// transitively reachable from Client Components (via utils/helpers.ts ->
4	// utils/url-filters.ts -> UrlFiltersContext.tsx), and Next.js forbids defining
5	// an inline `"use cache"` function in a file that can be pulled into a client
6	// bundle. See docs/incidents/2026-06-13-cachecomponents-metadata-resume-mismatch.md.
7	import { cacheLife, cacheTag } from "next/cache";
8	import { PlaceResponseDTO } from "types/api/place";
9	import { RegionsGroupedByCitiesResponseDTO } from "types/api/region";
10	import type { PlaceTypeAndLabel } from "types/common";
11	import {
12	  getInternalApiUrl,
13	  getVercelProtectionBypassHeaders,
14	} from "@utils/api-helpers";
15	import { placesTag, placeTag, regionsTag, regionsOptionsTag } from "@lib/cache/tags";
16	import { resolvePlaceTypeAndLabel } from "@utils/location-helpers";
17	
18	// Resolves the API origin from configuration instead of request headers(), so
19	// generateMetadata stays prerenderable under cacheComponents. Mirrors
20	// fetchCategoriesForMetadata / getNewsBySlugForMetadata.
21	export async function fetchPlaceBySlugForMetadata(
22	  slug: string,
23	): Promise<PlaceResponseDTO | null> {
24	  "use cache";
25	  cacheTag(placesTag, placeTag(slug));
26	  const encodedSlug = encodeURIComponent(slug);
27	  const url = await getInternalApiUrl(`/api/places/${encodedSlug}`, {
28	    preferConfiguredOrigin: true,
29	  });
30	  const response = await fetch(url, {
31	    headers: getVercelProtectionBypassHeaders(),
32	    next: { revalidate: 86400, tags: [placesTag, placeTag(slug)] },
33	  });
34	  if (response.status === 404) {
35	    // Genuine 404: cache briefly so a newly-created place isn't stuck on
36	    // "not found" metadata for hours. "minutes" not "seconds" — seconds is a
37	    // PPR dynamic hole and would re-break the static shell. Mirrors
38	    // getNewsBySlugForMetadata / getEventBySlugForMetadata.
39	    cacheLife("minutes");
40	    return null;
41	  }
42	  if (!response.ok) {
43	    throw new Error(`Failed to fetch place ${slug}: HTTP ${response.status}`);
44	  }
45	  cacheLife("hours");
46	  return response.json();
47	}
48	
49	export async function fetchRegionsWithCitiesForMetadata(): Promise<
50	  RegionsGroupedByCitiesResponseDTO[]
51	> {
52	  "use cache";
53	  cacheTag(regionsTag, regionsOptionsTag);
54	  const url = await getInternalApiUrl(`/api/regions/options`, {
55	    preferConfiguredOrigin: true,
56	  });
57	  const response = await fetch(url, {
58	    headers: getVercelProtectionBypassHeaders(),
59	    next: { revalidate: 86400, tags: [regionsTag, regionsOptionsTag] },
60	  });
61	  if (!response.ok) {
62	    cacheLife("minutes");
63	    return [];
64	  }
65	  cacheLife("hours");
66	  return response.json();
67	}
68	
69	export async function getPlaceTypeAndLabelForMetadata(
70	  place: string,
71	): Promise<PlaceTypeAndLabel> {
72	  "use cache";
73	  cacheTag(placesTag, regionsTag, regionsOptionsTag);
74	  cacheLife("hours");
75	  return resolvePlaceTypeAndLabel(
76	    place,
77	    fetchPlaceBySlugForMetadata,
78	    fetchRegionsWithCitiesForMetadata,
79	  );
80	}
